public class GJChronology_getInstance_TriageGen2Test {





    @Test
    public void testGetInstance_NonUTC_Zone() {
        // Tests the branch where zone is not UTC (triggers the recursive call and ZonedChronology)
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        Instant cutover = new Instant(987654321L);

        GJChronology chrono = GJChronology.getInstance(zone, cutover, 4);

        assertNotNull(chrono);
        assertEquals(zone, chrono.getZone());
        assertEquals(cutover, chrono.getGregorianCutover());
        assertEquals(4, chrono.getMinimumDaysInFirstWeek());
    }






