/**
 * Unit tests for GJChronology.getInstance
 */
public class GJChronology_getInstance_TriageGen2Test {







    @Test
    public void testGetInstance_CachingDifferentParameters() {
        // Tests that different parameters result in different instances (not returning from cache)
        DateTimeZone zone = DateTimeZone.UTC;

        GJChronology chrono1 = GJChronology.getInstance(zone, null, 4);
        GJChronology chrono2 = GJChronology.getInstance(zone, null, 5); // Different minDays

        Instant cutover = new Instant(1000L);
        GJChronology chrono3 = GJChronology.getInstance(zone, cutover, 4); // Different cutover

        assertNotNull(chrono1);
        assertNotNull(chrono2);
        assertNotNull(chrono3);

        assertNotSame("Different minDaysInFirstWeek should produce different instance", chrono1, chrono2);
        assertNotSame("Different cutover should produce different instance", chrono1, chrono3);
    }




}

